type ConfLevel = "alta" | "media";

type Confidence = {
  debitore: ConfLevel;
  cf: ConfLevel;
  importo: ConfLevel;
  scadenza: ConfLevel;
  tribunale: ConfLevel;
};

type PositionFields = {
  debitore: string;
  cf: string;
  creditore: string;
  importo: number | string;
  scadenza: string;
  contrattoN: string;
  tipoTitolo: string;
  tribunale: string;
  note: string;
};

type BaseStatus = "da-estrarre" | "pronto" | "generato" | "esportato";
type RowStatus = BaseStatus | "da-validare";

type PortfolioRow = {
  id: string;
  docs: string[];
  baseStatus: BaseStatus;
  fields: PositionFields;
  conf: Confidence;
  draftText: string;
};

type Issue = { key: string; label: string };

type DrawerState = { type: "mapping" | "preview"; id?: string };

const LOGO_SRC = "data:image/png;base64,";
const BRAND = "#0F4C9D";

