function buildInitialRows(): PortfolioRow[] {
  return RAW_ROWS.map((r, i) => ({
    id: `pos-${i + 1}`,
    docs: r.docs,
    baseStatus: "da-estrarre", // da-estrarre | pronto | generato | esportato
    fields: {
      debitore: r.debitore,
      cf: r.cf,
      creditore: r.creditore,
      importo: r.importo,
      scadenza: r.scadenza,
      contrattoN: r.contrattoN,
      tipoTitolo: r.tipoTitolo,
      tribunale: r.tribunale,
      note: "",
    },
    conf: r.conf,
    draftText: "",
  }));
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const eur = (n: number | string) =>
  new Intl.NumberFormat("it-IT", { style: "currency", currency: "EUR", maximumFractionDigits: 0 }).format(
    Number(n) || 0
  );

function formatMinutes(m: number) {
  if (m < 60) return `${m} min`;
  const h = Math.floor(m / 60);
  const rest = m % 60;
  return rest === 0 ? `${h} h` : `${h} h ${rest} min`;
}

function computeIssues(rows: PortfolioRow[], dismissed: Set<string>) {
  const groups: Record<string, string[]> = {};
  rows.forEach((r) => {
    if (r.fields.debitore && r.fields.importo) {
      const key = r.fields.debitore.trim().toLowerCase() + "|" + r.fields.importo;
      groups[key] = groups[key] || [];
      groups[key].push(r.id);
    }
  });

  const map: Record<string, Issue[]> = {};
  rows.forEach((r) => {
    const list = [];
    if (!r.fields.cf || !r.fields.cf.trim()) list.push({ key: "cf", label: "CF / P.IVA mancante" });
    if (!r.fields.importo || Number(r.fields.importo) === 0)
      list.push({ key: "importo", label: "Importo pari a zero" });
    if (!r.fields.tipoTitolo || !r.fields.tipoTitolo.trim()) list.push({ key: "titolo", label: "Titolo assente" });
    if (!r.fields.tribunale || !r.fields.tribunale.trim())
      list.push({ key: "tribunale", label: "Tribunale non indicato" });
    const key = (r.fields.debitore || "").trim().toLowerCase() + "|" + r.fields.importo;
    if (r.fields.debitore && r.fields.importo && groups[key] && groups[key].length > 1)
      list.push({ key: "duplicato", label: "Posizione duplicata (stesso debitore e importo)" });

    map[r.id] = list.filter((i) => !dismissed.has(r.id + ":" + i.key));
  });
  return map;
}

function generateDraft(row: PortfolioRow) {
  const f = row.fields;
  const docsList = row.docs.length ? row.docs.join(", ") : "documentazione a supporto del credito";
  return `TRIBUNALE DI ${f.tribunale ? f.tribunale.toUpperCase() : "[TRIBUNALE NON INDICATO]"}

RICORSO PER DECRETO INGIUNTIVO
(artt. 633 e ss. c.p.c.)

PARTI
Ricorrente: ${f.creditore}, in persona del legale rappresentante pro tempore.
Intimato/a: ${f.debitore}, C.F./P.IVA ${f.cf || "[dato mancante]"}.

FATTO
Il/la ricorrente vanta un credito certo, liquido ed esigibile nei confronti dell'intimato/a, derivante da ${
    f.tipoTitolo || "[titolo non indicato]"
  } n. ${f.contrattoN}, per l'importo di ${eur(f.importo)}, scaduto in data ${
    f.scadenza
  } e rimasto insoluto nonostante le richieste di pagamento formulate in via stragiudiziale.

PROVA SCRITTA
A sostegno del credito si producono: ${docsList}, atti idonei a costituire prova scritta del credito ai sensi e per gli effetti dell'art. 633 c.p.c.

DOMANDA
Si chiede che l'Ill.mo Tribunale adito voglia ingiungere all'intimato/a il pagamento della somma di ${eur(
    f.importo
  )}, oltre interessi legali dalla data di scadenza al saldo effettivo, e delle spese della procedura monitoria.

CONCLUSIONI
Piaccia all'Ill.mo Tribunale pronunciare decreto ingiuntivo provvisoriamente esecutivo ex art. 642 c.p.c. per l'importo sopra indicato, oltre interessi e spese, con fissazione del termine per l'eventuale opposizione.

${f.note ? `Note pratica: ${f.note}\n\n` : ""}[Luogo], [data]
Avv. — per ${f.creditore}

— bozza generata da Lexroom, non rivista da un professionista —`;
}

// ---------------------------------------------------------------------------
// Small UI atoms
// ---------------------------------------------------------------------------

function StatusPill({ status }: { status: RowStatus }) {
  const map: Record<RowStatus, { label: string; cls: string }> = {
    "da-estrarre": { label: "Da estrarre", cls: "bg-slate-100 text-slate-500 border-slate-200" },
    pronto: { label: "Pronto", cls: "bg-amber-50 text-amber-800 border-amber-200" },
    generato: { label: "Generato", cls: "bg-teal-50 text-teal-800 border-teal-200" },
    "da-validare": { label: "Da validare", cls: "bg-rose-50 text-rose-800 border-rose-200" },
    esportato: { label: "Esportato", cls: "bg-slate-900 text-white border-slate-900" },
  };
  const s = map[status] || map["da-estrarre"];
  return (
    <span className={`inline-flex items-center rounded-sm border px-2 py-0.5 text-xs font-medium ${s.cls}`}>
      {s.label}
    </span>
  );
}

function ConfDot({ level }: { level: ConfLevel }) {
  if (level !== "media") return null;
  return (
    <span
      title="Confidenza media — verifica il dato"
      className="ml-1 inline-block h-1.5 w-1.5 rounded-full bg-amber-500 align-middle"
    />
  );
}

function FieldInput({
  value,
  onChange,
  error,
  mono,
  placeholder,
}: {
  value: string | number;
  onChange: (value: string) => void;
  error?: boolean;
  mono?: boolean;
  placeholder?: string;
}) {
  return (
    <input
      value={value}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder}
      className={`w-full min-w-[7rem] rounded-sm border-b bg-transparent px-1 py-0.5 text-sm outline-none transition-colors ${
        mono ? "font-mono text-xs" : ""
      } ${
        error
          ? "border-rose-400 bg-rose-50 text-rose-900"
          : "border-transparent text-slate-800 hover:border-slate-300 focus:border-amber-600"
      }`}
    />
  );
}

// ---------------------------------------------------------------------------
// Main app
// ---------------------------------------------------------------------------

export default function App() {
  const [rows, setRows] = useState<PortfolioRow[]>([]);
  const [uploading, setUploading] = useState(false);

  const [extracting, setExtracting] = useState(false);
  const [extractIdx, setExtractIdx] = useState(0);

  const [generating, setGenerating] = useState(false);
  const [genIdx, setGenIdx] = useState(0);
  const [validationRun, setValidationRun] = useState(false);

  const [dismissed, setDismissed] = useState<Set<string>>(new Set());
  const [exported, setExported] = useState(false);

  const [drawer, setDrawer] = useState<DrawerState | null>(null);
  const [drawerOpen, setDrawerOpen] = useState(false);

  const [toast, setToast] = useState<string | null>(null);
  const toastTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  function showToast(msg: string) {
    setToast(msg);
    if (toastTimer.current) clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(null), 3200);
  }

  function openDrawer(d: DrawerState) {
    setDrawer(d);
    requestAnimationFrame(() => setDrawerOpen(true));
  }
  function closeDrawer() {
    setDrawerOpen(false);
    setTimeout(() => setDrawer(null), 200);
  }

  // ---- load data -----------------------------------------------------------

  function loadDemoDataset() {
    setRows(buildInitialRows());
    showToast("Dataset demo caricato: 12 posizioni");
  }

  function simulateUpload() {
    setUploading(true);
    setTimeout(() => {
      setRows(buildInitialRows());
      setUploading(false);
      showToast("Portafoglio caricato: 12 posizioni, documenti allegati");
    }, 900);
  }

  function resetAll() {
    setRows([]);
    setExtracting(false);
    setExtractIdx(0);
    setGenerating(false);
    setGenIdx(0);
    setValidationRun(false);
    setDismissed(new Set());
    setExported(false);
    closeDrawer();
  }

  // ---- extraction animation -------------------------------------------------

  useEffect(() => {
    if (!extracting) return;
    if (extractIdx >= rows.length) {
      setExtracting(false);
      showToast("Estrazione completata su tutte le posizioni");
      return;
    }
    const t = setTimeout(() => {
      setRows((prev) => prev.map((r, i) => (i === extractIdx ? { ...r, baseStatus: "pronto" } : r)));
      setExtractIdx((i) => i + 1);
    }, 240);
    return () => clearTimeout(t);
  }, [extracting, extractIdx, rows.length]);

  function runExtraction() {
    setExtractIdx(0);
    setExtracting(true);
  }

  // ---- generation animation --------------------------------------------------

  useEffect(() => {
    if (!generating) return;
    if (genIdx >= rows.length) {
      setGenerating(false);
      setValidationRun(true);
      const issues = computeIssues(rows, dismissed);
      const flagged = Object.values(issues).filter((l) => l.length > 0).length;
      showToast(
        flagged > 0
          ? `Generazione completata — errori × ${flagged} pratiche da validare`
          : "Generazione completata — nessun errore rilevato"
      );
      return;
    }
    const t = setTimeout(() => {
      setRows((prev) =>
        prev.map((r, i) => (i === genIdx ? { ...r, baseStatus: "generato", draftText: generateDraft(r) } : r))
      );
      setGenIdx((i) => i + 1);
    }, 260);
    return () => clearTimeout(t);
  }, [generating, genIdx, rows.length]); // eslint-disable-line react-hooks/exhaustive-deps

  function runGeneration() {
    setGenIdx(0);
    setGenerating(true);
  }

  // ---- field edits + issues ---------------------------------------------------

  function updateField(id: string, key: keyof PositionFields, value: string) {
    setRows((prev) => prev.map((r) => (r.id === id ? { ...r, fields: { ...r.fields, [key]: value } } : r)));
  }

  const issuesMap = useMemo(
    () => (validationRun ? computeIssues(rows, dismissed) : ({} as Record<string, Issue[]>)),
    [rows, dismissed, validationRun]
  );

  const activeBlockers = useMemo(
    () => Object.values(issuesMap).filter((l) => l.length > 0).length,
    [issuesMap]
  );

  function dismissIssue(rowId: string, issueKey: string) {
    setDismissed((prev) => {
      const next = new Set(prev);
      next.add(rowId + ":" + issueKey);
      return next;
    });
  }

  function derivedStatus(row: PortfolioRow): RowStatus {
    if (row.baseStatus === "esportato") return "esportato";
    if (row.baseStatus === "generato" && validationRun && (issuesMap[row.id] || []).length > 0) return "da-validare";
    return row.baseStatus;
  }

  // ---- derived aggregates -----------------------------------------------------

  const allLoaded = rows.length > 0;
  const noneExtracted = allLoaded && rows.every((r) => r.baseStatus === "da-estrarre");
  const allExtracted = allLoaded && rows.every((r) => r.baseStatus !== "da-estrarre");
  const allGenerated = allLoaded && rows.every((r) => r.baseStatus === "generato" || r.baseStatus === "esportato");
  const canExport = allGenerated && validationRun && activeBlockers === 0 && !exported;

  const generatedCount = rows.filter((r) => r.baseStatus === "generato" || r.baseStatus === "esportato").length;
  const totalClaimed = rows.reduce((s, r) => s + (Number(r.fields.importo) || 0), 0);
  const minutesSaved = generatedCount * 12;

  const STEPS = [
    { key: "portafoglio", label: "Portafoglio" },
    { key: "estrazione", label: "Estrazione" },
    { key: "generazione", label: "Generazione" },
    { key: "validazione", label: "Validazione" },
    { key: "esportazione", label: "Esportazione" },
  ];
  let currentStep = 0;
  if (!allLoaded) currentStep = 0;
  else if (noneExtracted || extracting) currentStep = 1;
  else if (allExtracted && !allGenerated) currentStep = 2;
  else if (allGenerated && !exported) currentStep = activeBlockers > 0 ? 3 : 4;
  else if (exported) currentStep = 4;

  // ---- export --------------------------------------------------------------

  function exportPackage() {
    const bundle = rows
      .map((r, i) => `POSIZIONE ${i + 1} — ${r.fields.debitore}\n${"=".repeat(60)}\n\n${r.draftText}`)
      .join("\n\n\n");
    const blob = new Blob([bundle], { type: "text/markdown;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "lexroom-decreti-ingiuntivi-export.md";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

    setRows((prev) => prev.map((r) => ({ ...r, baseStatus: "esportato" })));
    setExported(true);
    showToast(`Pacchetto esportato: ${rows.length} decreti pronti al deposito`);
  }

  async function copyDraft(text: string) {
    try {
      await navigator.clipboard.writeText(text);
      showToast("Bozza copiata negli appunti");
    } catch {
      showToast("Copia non disponibile in questo ambiente");
    }
  }

  const previewRow = drawer && drawer.type === "preview" ? rows.find((r) => r.id === drawer.id) : null;

  // ---------------------------------------------------------------------------

  return (
    <div className="min-h-screen bg-slate-100 font-sans text-slate-900">
      {/* Header */}
      <div className="border-b border-slate-200 bg-white">
        <div className="mx-auto flex max-w-7xl flex-wrap items-center justify-between gap-3 px-6 py-4">
          <div>
            <div className="flex items-center gap-3">
              <img src={LOGO_SRC} alt="Lexroom" className="h-6 w-auto" />
              <span className="h-5 w-px bg-slate-200" />
              <h1 className="font-serif text-xl text-slate-900">Decreti NPL — MVP bulk</h1>
            </div>
            <p className="mt-0.5 text-sm text-slate-500">Un portafoglio, n decreti pronti al deposito</p>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => allLoaded && openDrawer({ type: "mapping" })}
              disabled={!allLoaded}
              className="inline-flex items-center gap-1.5 rounded-sm border border-slate-200 px-3 py-1.5 text-sm text-slate-600 hover:border-slate-300 hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-40"
            >
              <LayoutTemplate className="h-3.5 w-3.5" />
              Mappatura template
            </button>
            {allLoaded && (
              <button
                onClick={resetAll}
                className="inline-flex items-center gap-1.5 rounded-sm border border-slate-200 px-3 py-1.5 text-sm text-slate-500 hover:border-slate-300 hover:bg-slate-50"
              >
                <RotateCcw className="h-3.5 w-3.5" />
                Ricomincia
              </button>
            )}
          </div>
        </div>

        {/* Stepper */}
        {allLoaded && (
          <div className="mx-auto flex max-w-7xl items-center gap-2 px-6 pb-3 text-sm">
            {STEPS.map((s, i) => (
              <React.Fragment key={s.key}>
                <div className="flex items-center gap-1.5">
                  <span
                    className={`flex h-5 w-5 items-center justify-center rounded-full text-xs ${
                      i < currentStep
                        ? "bg-slate-900 text-white"
                        : i === currentStep
                        ? "text-white"
                        : "bg-slate-100 text-slate-400"
                    }`}
                    style={i === currentStep ? { backgroundColor: BRAND } : undefined}
                  >
                    {i < currentStep ? <CheckCircle2 className="h-3 w-3" /> : i + 1}
                  </span>
                  <span className={i === currentStep ? "font-medium text-slate-900" : "text-slate-400"}>
                    {s.label}
                  </span>
                </div>
                {i < STEPS.length - 1 && <ChevronRight className="h-3.5 w-3.5 text-slate-300" />}
              </React.Fragment>
            ))}
          </div>
        )}
      </div>

      {/* Main */}
      <div className="mx-auto max-w-7xl px-6 py-6 pb-28">
        {!allLoaded ? (
          <div className="mx-auto mt-10 max-w-xl rounded border border-slate-200 bg-white p-10 text-center">
            <FileText className="mx-auto mb-3 h-8 w-8" style={{ color: BRAND }} />
            <h2 className="font-serif text-lg text-slate-900">1 cartella → n decreti pronti al deposito</h2>
            <p className="mt-2 text-sm text-slate-500">
              Carica un portafoglio di posizioni NPL e Lexroom estrae i dati, mappa il template del decreto
              ingiuntivo e genera una bozza per ciascuna pratica, con una validazione prima dell'esportazione.
            </p>
            <div className="mt-6 flex flex-col items-center gap-2">
              <button
                onClick={simulateUpload}
                disabled={uploading}
                className="inline-flex w-full items-center justify-center gap-2 rounded-sm px-4 py-2.5 text-sm font-medium text-white transition hover:brightness-110 disabled:opacity-60"
                style={{ backgroundColor: BRAND }}
              >
                <Upload className="h-4 w-4" />
                {uploading ? "Caricamento in corso…" : "Carica portafoglio NPL"}
              </button>
              <button
                onClick={loadDemoDataset}
                className="text-sm text-slate-500 underline decoration-slate-300 underline-offset-4 hover:text-slate-700"
              >
                Carica dataset demo (12 posizioni)
              </button>
            </div>
          </div>
        ) : (
          <>
            {/* Metrics */}
            <div className="mb-4 grid grid-cols-2 gap-3 sm:grid-cols-4">
              <MetricCard label="Posizioni" value={rows.length} />
              <MetricCard label="Decreti generati" value={`${generatedCount}/${rows.length}`} />
              <MetricCard label="Totale reclamato" value={eur(totalClaimed)} />
              <MetricCard label="Tempo stimato risparmiato" value={formatMinutes(minutesSaved)} />
            </div>

            {/* Table */}
            <div className="overflow-x-auto rounded border border-slate-200 bg-white">
              <table className="w-full min-w-[1080px] border-collapse text-left text-sm">
                <thead>
                  <tr className="border-b border-slate-200 bg-slate-50 text-xs text-slate-500">
                    <th className="px-3 py-2 font-medium">Stato</th>
                    <th className="px-3 py-2 font-medium">Debitore</th>
                    <th className="px-3 py-2 font-medium">CF / P.IVA</th>
                    <th className="px-3 py-2 font-medium">Creditore</th>
                    <th className="px-3 py-2 font-medium">Importo</th>
                    <th className="px-3 py-2 font-medium">Scadenza</th>
                    <th className="px-3 py-2 font-medium">Titolo</th>
                    <th className="px-3 py-2 font-medium">Tribunale</th>
                    <th className="px-3 py-2 font-medium">Documenti</th>
                    <th className="px-3 py-2 font-medium">Azioni</th>
                  </tr>
                </thead>
                <tbody>
                  {rows.map((r, idx) => {
                    const status = derivedStatus(r);
                    const revealed = r.baseStatus !== "da-estrarre";
                    const issues = issuesMap[r.id] || [];
                    return (
                      <React.Fragment key={r.id}>
                        <tr className="border-b border-slate-100 align-top hover:bg-slate-50/60">
                          <td className="px-3 py-2">
                            <StatusPill status={status} />
                          </td>
                          <td className="px-3 py-2">
                            {revealed ? (
                              <span className="flex items-center text-sm text-slate-800">
                                {r.fields.debitore}
                                <ConfDot level={r.conf.debitore} />
                              </span>
                            ) : (
                              <span className="text-slate-300">—</span>
                            )}
                          </td>
                          <td className="px-3 py-2">
                            {revealed ? (
                              <FieldInput
                                value={r.fields.cf}
                                onChange={(v) => updateField(r.id, "cf", v)}
                                error={issues.some((i) => i.key === "cf")}
                                mono
                                placeholder="mancante"
                              />
                            ) : (
                              <span className="text-slate-300">—</span>
                            )}
                          </td>
                          <td className="px-3 py-2 text-sm text-slate-600">{revealed ? r.fields.creditore : <span className="text-slate-300">—</span>}</td>
                          <td className="px-3 py-2">
                            {revealed ? (
                              <span className="flex items-center text-sm">
                                <FieldInput
                                  value={r.fields.importo}
                                  onChange={(v) => updateField(r.id, "importo", v.replace(/[^0-9]/g, ""))}
                                  error={issues.some((i) => i.key === "importo")}
                                />
                                <ConfDot level={r.conf.importo} />
                              </span>
                            ) : (
                              <span className="text-slate-300">—</span>
                            )}
                          </td>
                          <td className="px-3 py-2">
                            {revealed ? (
                              <span className="flex items-center text-sm text-slate-700">
                                {r.fields.scadenza}
                                <ConfDot level={r.conf.scadenza} />
                              </span>
                            ) : (
                              <span className="text-slate-300">—</span>
                            )}
                          </td>
                          <td className="px-3 py-2">
                            {revealed ? (
                              <FieldInput
                                value={r.fields.tipoTitolo}
                                onChange={(v) => updateField(r.id, "tipoTitolo", v)}
                                error={issues.some((i) => i.key === "titolo")}
                                placeholder="assente"
                              />
                            ) : (
                              <span className="text-slate-300">—</span>
                            )}
                          </td>
                          <td className="px-3 py-2">
                            {revealed ? (
                              <span className="flex items-center text-sm">
                                <FieldInput
                                  value={r.fields.tribunale}
                                  onChange={(v) => updateField(r.id, "tribunale", v)}
                                  error={issues.some((i) => i.key === "tribunale")}
                                  placeholder="non indicato"
                                />
                                <ConfDot level={r.conf.tribunale} />
                              </span>
                            ) : (
                              <span className="text-slate-300">—</span>
                            )}
                          </td>
                          <td className="px-3 py-2">
                            <div className="flex max-w-[160px] flex-wrap gap-1">
                              {r.docs.map((d) => (
                                <span
                                  key={d}
                                  className="rounded-sm border border-slate-200 bg-slate-50 px-1.5 py-0.5 text-xs text-slate-500"
                                >
                                  {d}
                                </span>
                              ))}
                            </div>
                          </td>
                          <td className="px-3 py-2">
                            {(status === "generato" || status === "da-validare" || status === "esportato") && (
                              <button
                                onClick={() => openDrawer({ type: "preview", id: r.id })}
                                className="inline-flex items-center gap-1 text-xs font-medium hover:brightness-110"
                                style={{ color: BRAND }}
                              >
                                <Eye className="h-3.5 w-3.5" />
                                Anteprima
                              </button>
                            )}
                          </td>
                        </tr>
                        {issues.length > 0 && (
                          <tr className="border-b border-rose-100 bg-rose-50/70">
                            <td colSpan={10} className="px-3 py-1.5">
                              <div className="flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-rose-800">
                                <span className="inline-flex items-center gap-1 font-medium">
                                  <AlertTriangle className="h-3.5 w-3.5" />
                                  {idx + 1}.
                                </span>
                                {issues.map((iss) => (
                                  <span key={iss.key} className="inline-flex items-center gap-1.5">
                                    {iss.label}
                                    <button
                                      onClick={() => dismissIssue(r.id, iss.key)}
                                      className="text-rose-400 underline decoration-dotted underline-offset-2 hover:text-rose-600"
                                    >
                                      ignora
                                    </button>
                                  </span>
                                ))}
                              </div>
                            </td>
                          </tr>
                        )}
                      </React.Fragment>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </>
        )}
      </div>

      {/* Bottom action bar */}
      {allLoaded && (
        <div className="fixed inset-x-0 bottom-0 border-t border-slate-200 bg-white">
          <div className="mx-auto flex max-w-7xl flex-wrap items-center justify-between gap-3 px-6 py-3">
            <div className="min-w-[220px] flex-1">
              {extracting && (
                <ProgressLine label={`Estrazione in corso… ${extractIdx}/${rows.length}`} pct={(extractIdx / rows.length) * 100} />
              )}
              {generating && (
                <ProgressLine label={`Generazione in corso… ${genIdx}/${rows.length}`} pct={(genIdx / rows.length) * 100} />
              )}
              {!extracting && !generating && allGenerated && !exported && (
                <div className="text-sm">
                  {activeBlockers > 0 ? (
                    <span className="inline-flex items-center gap-1.5 text-rose-700">
                      <AlertTriangle className="h-4 w-4" />
                      errori × {activeBlockers} pratiche — risolvi o ignora prima di esportare
                    </span>
                  ) : (
                    <span className="inline-flex items-center gap-1.5 text-teal-700">
                      <CheckCircle2 className="h-4 w-4" />
                      Validazione superata — pronto per l'esportazione
                    </span>
                  )}
                </div>
              )}
              {exported && (
                <span className="inline-flex items-center gap-1.5 text-sm text-slate-500">
                  <CheckCircle2 className="h-4 w-4 text-teal-700" />
                  Pacchetto esportato — {rows.length} decreti pronti al deposito
                </span>
              )}
              {!extracting && !generating && noneExtracted && (
                <span className="text-sm text-slate-500">{rows.length} posizioni caricate, pronte per l'estrazione</span>
              )}
              {!extracting && !generating && allExtracted && !allGenerated && (
                <span className="text-sm text-slate-500">Dati estratti — verifica i campi e genera le bozze</span>
              )}
            </div>

            <div className="flex items-center gap-2">
              {!extracting && noneExtracted && (
                <button
                  onClick={runExtraction}
                  className="inline-flex items-center gap-2 rounded-sm bg-slate-900 px-4 py-2 text-sm font-medium text-white hover:bg-slate-800"
                >
                  <CircleDot className="h-4 w-4" />
                  Estrai dati ({rows.length} posizioni)
                </button>
              )}
              {!generating && allExtracted && !allGenerated && (
                <button
                  onClick={runGeneration}
                  className="inline-flex items-center gap-2 rounded-sm px-4 py-2 text-sm font-medium text-white transition hover:brightness-110"
                  style={{ backgroundColor: BRAND }}
                >
                  <Sparkles className="h-4 w-4" />
                  Genera {rows.length} decreti
                </button>
              )}
              {allGenerated && !exported && (
                <button
                  onClick={exportPackage}
                  disabled={!canExport}
                  className="inline-flex items-center gap-2 rounded-sm bg-slate-900 px-4 py-2 text-sm font-medium text-white hover:bg-slate-800 disabled:cursor-not-allowed disabled:bg-slate-300"
                >
                  <Download className="h-4 w-4" />
                  Esporta pacchetto
                </button>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Toast */}
      {toast && (
        <div className="fixed bottom-20 right-6 z-50 rounded-sm bg-slate-900 px-4 py-2 text-sm text-white shadow-lg">
          {toast}
        </div>
      )}

      {/* Drawer */}
      {drawer && (
        <div className="fixed inset-0 z-40 flex justify-end">
          <div
            className={`absolute inset-0 bg-slate-900/30 transition-opacity duration-200 ${
              drawerOpen ? "opacity-100" : "opacity-0"
            }`}
            onClick={closeDrawer}
          />
          <div
            className={`relative h-full w-full max-w-md overflow-y-auto bg-white shadow-xl transition-transform duration-200 ${
              drawerOpen ? "translate-x-0" : "translate-x-full"
            }`}
          >
            <div className="flex items-center justify-between border-b border-slate-200 px-5 py-4">
              <h3 className="font-serif text-base text-slate-900">
                {drawer.type === "mapping" && "Mappatura template"}
                {drawer.type === "preview" && "Anteprima decreto"}
              </h3>
              <button onClick={closeDrawer} className="text-slate-400 hover:text-slate-700">
                <X className="h-4 w-4" />
              </button>
            </div>

            <div className="px-5 py-4">
              {drawer.type === "mapping" && <MappingContent />}
              {drawer.type === "preview" && previewRow && (
                <div>
                  <div className="mb-3 flex items-center justify-between">
                    <span className="text-sm text-slate-500">{previewRow.fields.debitore}</span>
                    <button
                      onClick={() => copyDraft(previewRow.draftText)}
                      className="inline-flex items-center gap-1.5 text-xs font-medium hover:brightness-110"
                      style={{ color: BRAND }}
                    >
                      <Copy className="h-3.5 w-3.5" />
                      Copia bozza
                    </button>
                  </div>
                  <div className="whitespace-pre-wrap rounded border border-slate-300 bg-white p-5 font-serif text-sm leading-relaxed text-slate-800 shadow-inner">
                    {previewRow.draftText}
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Supporting components
// ---------------------------------------------------------------------------

function MetricCard({ label, value }: { label: string; value: string | number }) {
  return (
    <div className="rounded border border-slate-200 bg-white px-4 py-3">
      <div className="text-xs text-slate-500">{label}</div>
      <div className="mt-1 font-serif text-lg text-slate-900">{value}</div>
    </div>
  );
}

function ProgressLine({ label, pct }: { label: string; pct: number }) {
  return (
    <div>
      <div className="mb-1 text-sm text-slate-600">{label}</div>
      <div className="h-1.5 w-full max-w-sm overflow-hidden rounded-full bg-slate-100">
        <div className="h-full bg-amber-600 transition-all" style={{ width: `${pct}%` }} />
      </div>
    </div>
  );
}

function MappingContent() {
  const rows = [
    { section: "Parti", fields: "{{creditore}}, {{debitore}}, {{cf}}" },
    { section: "Fatti", fields: "{{tipoTitolo}}, {{contrattoN}}, {{importo}}, {{scadenza}}" },
    { section: "Prova scritta", fields: "{{docs}}" },
    { section: "Domanda", fields: "{{importo}}" },
    { section: "Conclusioni", fields: "testo di rito, nessun dato dinamico" },
  ];
  return (
    <div>
      <p className="mb-4 text-sm text-slate-600">
        Il template del decreto ingiuntivo è fisso: cambiano solo i placeholder popolati dai dati estratti.
      </p>
      <div className="space-y-2">
        {rows.map((r) => (
          <div key={r.section} className="rounded border border-slate-200 px-3 py-2">
            <div className="text-sm font-medium text-slate-800">{r.section}</div>
            <div className="mt-0.5 font-mono text-xs" style={{ color: BRAND }}>{r.fields}</div>
          </div>
        ))}
      </div>
    </div>
  );
}
